changes = manifest["avatar_changes"]
storage = GuestTemplate._meta.get_field("avatar").storage
for row in changes:
    path = Path(settings.BASE_DIR) / row["source"]
    expected = "guests/portrait_" + hashlib.sha256(IMAGE_VERSION + path.read_bytes()).hexdigest() + ".webp"
    assert expected == row["target"]
    if not storage.exists(expected):
        content, _ = compress_and_resize_image(path, max_size=(400, 400), quality=85, convert_to_webp=True)
        assert storage.save(expected, content) == expected
with transaction.atomic():
    keys = ["hero_yang_zheng_purple", "hero_di_qinglin"]
    assert GuestTemplate.objects.filter(key__in=keys).count() == 2
    GuestTemplate.objects.filter(key__in=keys).update(growth_range=[6, 13])
    for row in changes:
        template = GuestTemplate.objects.select_for_update().get(key=row["key"])
        assert template.avatar.name == row["previous"]
        template.avatar.name = row["target"]
        template.save(update_fields=["avatar"])
    transaction.on_commit(clear_template_cache)
    transaction.on_commit(clear_guest_template_cache)
print(json.dumps({"growth_templates": 2, "avatar_templates": len(changes), "old_media_preserved": True}))
